            title = "Partition Pass/Fail Students and Compute Average Score",
            difficulty = "Hard",
            pattern = "partitioningBy(isPassed, averagingDouble(Score))",
            description = "Partition a list of students into passing (score >= 60) and failing, and compute the average score for each group.",
            inputData = "List<Student> students = Arrays.asList(\n    new Student(\"Dan\", 85),\n    new Student(\"Eli\", 50),\n    new Student(\"Fay\", 90),\n    new Student(\"Guy\", 40)\n);",
            expectedOutput = "Map<Boolean, Double> = {true: 87.5, false: 45.0}",
            functionalSolution = "public Map<Boolean, Double> avgScorePassFail(List<Student> students) {\n    return students.stream()\n        .collect(Collectors.partitioningBy(\n            s -> s.getScore() >= 60,\n            Collectors.averagingDouble(Student::getScore)\n        ));\n}",
            imperativeSolution = "public Map<Boolean, Double> avgScorePassFail(List<Student> students) {\n    double passSum = 0, failSum = 0;\n    int passCount = 0, failCount = 0;\n    for (Student s : students) {\n        if (s.getScore() >= 60) {\n            passSum += s.getScore();\n            passCount++;\n        } else {\n            failSum += s.getScore();\n            failCount++;\n        }\n    }\n    Map<Boolean, Double> res = new HashMap<>();\n    res.put(true, passCount > 0 ? passSum / passCount : 0.0);\n    res.put(false, failCount > 0 ? failSum / failCount : 0.0);\n    return res;\n}",
            comparisonInsight = "Downstream averaging collector directly pairs with partitioning to handle zero-count edge cases safely."
        ),
