            description = "Find the second highest salary across all employees in the organization, handling potential ties gracefully.",
            inputData = "List<Employee> employees = Arrays.asList(\n    new Employee(\"A\", 120000),\n    new Employee(\"B\", 120000),\n    new Employee(\"C\", 95000),\n    new Employee(\"D\", 80000)\n);",
            expectedOutput = "Optional<Double> = 95000.0",
            functionalSolution = "public Optional<Double> findSecondHighestSalary(List<Employee> employees) {\n    return employees.stream()\n        .map(Employee::getSalary)\n        .distinct()\n        .sorted(Comparator.reverseOrder())\n        .skip(1)\n        .findFirst();\n}",
            imperativeSolution = "public Optional<Double> findSecondHighestSalary(List<Employee> employees) {\n    Double highest = null, second = null;\n    for (Employee e : employees) {\n        double s = e.getSalary();\n        if (highest == null || s > highest) {\n            second = highest;\n            highest = s;\n        } else if (s < highest && (second == null || s > second)) {\n            second = s;\n        }\n    }\n    return Optional.ofNullable(second);\n}",
            comparisonInsight = "The stream pipeline is declarative and naturally handles duplicates with .distinct(), whereas the imperative approach requires careful dual pointer maintenance to avoid tie-condition bugs."
        ),
