            title = "Find Nth Highest Salary",
            difficulty = "Hard",
            pattern = "map(Salary).distinct().sorted(reverse).skip(n - 1).findFirst()",
            description = "Generalized method to find the Nth highest distinct salary in an employee list.",
            inputData = "List<Employee> employees = ...; int n = 3;",
            expectedOutput = "Optional<Double> representing 3rd highest distinct salary.",
            functionalSolution = "public Optional<Double> findNthHighestSalary(List<Employee> employees, int n) {\n    if (n <= 0) return Optional.empty();\n    return employees.stream()\n        .map(Employee::getSalary)\n        .distinct()\n        .sorted(Comparator.reverseOrder())\n        .skip(n - 1)\n        .findFirst();\n}",
            imperativeSolution = "public Optional<Double> findNthHighestSalary(List<Employee> employees, int n) {\n    if (n <= 0) return Optional.empty();\n    TreeSet<Double> distinctSalaries = new TreeSet<>(Comparator.reverseOrder());\n    for (Employee e : employees) {\n        distinctSalaries.add(e.getSalary());\n    }\n    int count = 0;\n    for (Double salary : distinctSalaries) {\n        count++;\n        if (count == n) return Optional.of(salary);\n    }\n    return Optional.empty();\n}",
            comparisonInsight = "Streams express pagination and ranking (skip + findFirst) effortlessly without instantiating explicit sorted collections."
        ),
