            functionalSolution = "public List<Map.Entry<String, Integer>> top5BestSellers(List<Order> orders) {\n    return orders.stream()\n        .flatMap(o -> o.getItems().stream())\n        .collect(Collectors.groupingBy(OrderItem::getProductId, Collectors.summingInt(OrderItem::getQuantity)))\n        .entrySet().stream()\n        .sorted(Map.Entry.<String, Integer>comparingByValue().reversed())\n        .limit(5)\n        .collect(Collectors.toList());\n}",
            imperativeSolution = "public List<Map.Entry<String, Integer>> top5BestSellers(List<Order> orders) {\n    Map<String, Integer> sales = new HashMap<>();\n    for (Order o : orders) {\n        for (OrderItem item : o.getItems()) {\n            sales.put(item.getProductId(), sales.getOrDefault(item.getProductId(), 0) + item.getQuantity());\n        }\n    }\n    List<Map.Entry<String, Integer>> entries = new ArrayList<>(sales.entrySet());\n    entries.sort((a, b) -> Integer.compare(b.getValue(), a.getValue()));\n    List<Map.Entry<String, Integer>> top5 = new ArrayList<>();\n    for (int i = 0; i < Math.min(5, entries.size()); i++) {\n        top5.add(entries.get(i));\n    }\n    return top5;\n}",
