            expectedOutput = "List<Integer> = [2, 3, 5, 7, 11, 13]",
            functionalSolution = "public List<Integer> filterPrimes(List<Integer> nums) {\n    return nums.stream()\n        .filter(this::isPrime)\n        .collect(Collectors.toList());\n}\n\nprivate boolean isPrime(int n) {\n    return n > 1 && IntStream.rangeClosed(2, (int) Math.sqrt(n)).noneMatch(d -> n % d == 0);\n}",
            imperativeSolution = "public List<Integer> filterPrimes(List<Integer> nums) {\n    List<Integer> primes = new ArrayList<>();\n    for (int n : nums) {\n        if (n > 1) {\n            boolean prime = true;\n            for (int d = 2; d * d <= n; d++) {\n                if (n % d == 0) {\n                    prime = false;\n                    break;\n                }\n            }\n            if (prime) primes.add(n);\n        }\n    }\n    return primes;\n}",
