            functionalSolution = "public List<Employee> searchEmployees(List<Employee> employees, SearchCriteria criteria) {\n    Predicate<Employee> predicate = e -> true;\n    if (criteria.getName() != null) {\n        predicate = predicate.and(e -> e.getName().equalsIgnoreCase(criteria.getName()));\n    }\n    if (criteria.getDepartment() != null) {\n        predicate = predicate.and(e -> e.getDepartment().equalsIgnoreCase(criteria.getDepartment()));\n    }\n    if (criteria.getMinSalary() != null) {\n        predicate = predicate.and(e -> e.getSalary() >= criteria.getMinSalary());\n    }\n    return employees.stream().filter(predicate).collect(Collectors.toList());\n}",
            imperativeSolution = "public List<Employee> searchEmployees(List<Employee> employees, SearchCriteria criteria) {\n    List<Employee> result = new ArrayList<>();\n    for (Employee e : employees) {\n        if (criteria.getName() != null && !e.getName().equalsIgnoreCase(criteria.getName())) continue;\n        if (criteria.getDepartment() != null && !e.getDepartment().equalsIgnoreCase(criteria.getDepartment())) continue;\n        if (criteria.getMinSalary() != null && e.getSalary() < criteria.getMinSalary()) continue;\n        result.add(e);\n    }\n    return result;\n}",
