            inputData = "[[1, 2, 3], [4, 5, 6]]",
            expectedOutput = "[[1, 4], [2, 5], [3, 6]]",
            functionalSolution = "public <T> List<List<T>> transpose(List<List<T>> matrix) {\n    if (matrix.isEmpty()) return Collections.emptyList();\n    int cols = matrix.get(0).size();\n    return IntStream.range(0, cols)\n        .mapToObj(col -> matrix.stream().map(row -> row.get(col)).collect(Collectors.toList()))\n        .collect(Collectors.toList());\n}",
            imperativeSolution = "public <T> List<List<T>> transpose(List<List<T>> matrix) {\n    if (matrix.isEmpty()) return Collections.emptyList();\n    int rows = matrix.size();\n    int cols = matrix.get(0).size();\n    List<List<T>> transposed = new ArrayList<>();\n    for (int c = 0; c < cols; c++) {\n        List<T> newRow = new ArrayList<>();\n        for (int r = 0; r < rows; r++) {\n            newRow.add(matrix.get(r).get(c));\n        }\n        transposed.add(newRow);\n    }\n    return transposed;\n}",
            comparisonInsight = "Combining IntStream index iteration with row mapping neatly handles 2D matrix transformation."
