            inputData = "List<String> words = Arrays.asList(\"radar\", \"hello\", \"level\", \"world\", \"madam\");",
            expectedOutput = "List<String> = [\"radar\", \"level\", \"madam\"]",
            functionalSolution = "public List<String> findPalindromes(List<String> words) {\n    return words.stream()\n        .filter(w -> w.equalsIgnoreCase(new StringBuilder(w).reverse().toString()))\n        .collect(Collectors.toList());\n}",
            imperativeSolution = "public List<String> findPalindromes(List<String> words) {\n    List<String> palindromes = new ArrayList<>();\n    for (String w : words) {\n        int l = 0, r = w.length() - 1;\n        boolean isPal = true;\n        while (l < r) {\n            if (Character.toLowerCase(w.charAt(l)) != Character.toLowerCase(w.charAt(r))) {\n                isPal = false;\n                break;\n            }\n            l++;\n            r--;\n        }\n        if (isPal) palindromes.add(w);\n    }\n    return palindromes;\n}",
            comparisonInsight = "The imperative two-pointer check avoids allocating StringBuilder objects, but the stream filter is significantly more concise."
