            functionalSolution = "public List<Integer> generateFibonacci(int n) {\n    return Stream.iterate(new int[]{0, 1}, f -> new int[]{f[1], f[0] + f[1]})\n        .limit(n)\n        .map(f -> f[0])\n        .collect(Collectors.toList());\n}",
